using LiAIChat.AI; using System.Net.Http; using System.Text; using System.Threading.Tasks;
namespace LiAIChat.Commentary { public class OpenAIEarthCommentaryGenerator { readonly HttpClient c; readonly string k; public OpenAIEarthCommentaryGenerator(HttpClient c,string k){this.c=c;this.k=k;} public async Task<string> GenerateAsync(string p){string j="{\"model\":\"gpt-5.6-luna\",\"input\":\""+p.Replace("\\","\\\\").Replace("\"","\\\"").Replace("\n","\\n")+"\",\"max_output_tokens\":1800}";using(var r=new HttpRequestMessage(HttpMethod.Post,"https://api.openai.com/v1/responses")){r.Headers.Add("Authorization","Bearer "+k);r.Content=new StringContent(j,Encoding.UTF8,"application/json");using(var x=await c.SendAsync(r).ConfigureAwait(false)){return OpenAIResponseParser.ExtractOutputText(await x.Content.ReadAsStringAsync().ConfigureAwait(false));}}} } }
